#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv)
{
    const size_t MAX_INPUT = 1024;
    char norm[MAX_INPUT + 1];
    size_t norm_len = 0;

    if (argc > 1) {
        const char *src = argv[1];
        size_t src_len = strlen(src);
        if (src_len > MAX_INPUT) {
            puts("TOO_LONG");
            return 0;
        }
        for (size_t i = 0; i < src_len; ++i) {
            unsigned char ch = (unsigned char)src[i];
            if (isalnum(ch)) {
                norm[norm_len++] = (char)toupper(ch);
            }
        }
    }
    norm[norm_len] = '\0';
    int is_pal = 1;
    for (size_t i = 0; i < norm_len / 2; ++i) {
        if (norm[i] != norm[norm_len - 1 - i]) {
            is_pal = 0;
            break;
        }
    }
    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
